param([string]$RepositoryRoot=(Split-Path -Parent (Split-Path -Parent $PSScriptRoot)))
$ErrorActionPreference='Stop'
. (Join-Path $PSScriptRoot '../lib/Stage3StaticAudit.Common.ps1')
function Body($s,$n){Get-AICFMethodBody ([pscustomobject]@{Source=$s;Code=(ConvertTo-AICFCodeText $s)}) $n}
$base=[IO.File]::ReadAllText((Join-Path $PSScriptRoot 'Test-UnstuckMutationScopeContracts.ps1'))
$cs=[regex]::Match($base,"(?s)\`$cs=@'\r?\n(.*?)\r?\n'@").Groups[1].Value
if(!$cs){throw 'Missing shared native adapter'}
$hint=[IO.File]::ReadAllText((Join-Path $RepositoryRoot 'AIConflictCore/Scripts/Game/AIConflict/State/Vehicles/AICF_UnstuckPathHint.c'))
$scope=[IO.File]::ReadAllText((Join-Path $RepositoryRoot 'AIConflictCore/Scripts/Game/AIConflict/State/Vehicles/AICF_UnstuckMutationScope.c'))
$flow=[IO.File]::ReadAllText((Join-Path $RepositoryRoot 'AIConflictCore/Scripts/Game/AIConflict/Vehicles/AICF_VehicleTransitFlow.c'))
$controller=[IO.File]::ReadAllText((Join-Path $RepositoryRoot 'AIConflictCore/Scripts/Game/AIConflict/Bootstrap/AICF_MatchController.c'))
function Translate($s){$s=$s.Replace('protected ','public ').Replace('EntityID','int').Replace('vector','Vec').Replace('System.GetTickCount()','Clock.GetTickCount()').Replace('.FindComponent(RplComponent)','.FindComponent(typeof(RplComponent))').Replace('.FindComponent(SCR_AIVehicleUsageComponent)','.FindComponent(typeof(SCR_AIVehicleUsageComponent))').Replace('%1:%2:%3:%4:%5:%6:%7:%8','{0}:{1}:{2}:{3}:{4}:{5}:{6}:{7}');return $s}
$scope=Translate $scope;$scope=$scope.Replace('class AICF_UnstuckMutationScope','public class AICF_UnstuckMutationScope:N').Replace('static AICF_UnstuckMutationScope Capture','public static AICF_UnstuckMutationScope Capture').Replace('bool IsCurrent()','public bool IsCurrent()')
$sample=Body $flow 'TryRelocateVehicleForUnstuck';$start=$sample.IndexOf('bool currentHint =');$end=$sample.IndexOf('vector angles = targetDirection.VectorToAngles();',$start);$boundary=$sample.Substring($start,$end-$start).Replace('float repeatedNearestPlayer;','double repeatedNearestPlayer=0;').Replace('allowManagedTransitionRecovery, safetyReason)','allowManagedTransitionRecovery, out safetyReason)').Replace('repeatedNearestPlayer, safetyReason)','out repeatedNearestPlayer, out safetyReason)').Replace('vehicle, safetyReason)','vehicle, out safetyReason)')
$cs=$cs.Replace('__SCOPE__',$scope).Replace('__FIND__',(Body $controller 'FindManagedInfantrySlot').Replace('AICF_GroupSlot slot;','AICF_GroupSlot slot=null;')).Replace('__BOUNDARY__',$boundary).Replace('AICFMutationActual','AICFHintIdentityActual')
$cs=$cs.Replace('public double X,Y,Z;','public double Length(){return System.Math.Sqrt(X*X+Y*Y+Z*Z);}public double X,Y,Z;').Replace('public int Id(){return Value;}','public bool IsMaster(){return Master;}public bool IsProxy(){return Proxy;}public int Id(){return Value;}')
$cs=$cs.Replace('public N FindComponent(Type t){return Rpl;}','public virtual N FindComponent(Type t){return Rpl;}')
$cs=$cs.Replace('public class SCR_AIGroup:IEntity {','public class SCR_AIGroup:IEntity {public AIWaypoint Waypoint;public List<AIWaypoint> Queue=new List<AIWaypoint>();public SCR_AIGroupUtilityComponent Utility;public AIWaypoint GetCurrentWaypoint(){return Waypoint;}public void GetWaypoints(List<AIWaypoint> q){q.AddRange(Queue);}')
$cs=$cs.Replace('public class Vehicle:IEntity {}','public class Vehicle:IEntity {public Physics Physics=new Physics();public SCR_AIVehicleUsageComponent Usage=new SCR_AIVehicleUsageComponent();public SCR_DamageManagerComponent Damage=new SCR_DamageManagerComponent();public bool CanMove=true,Fire;public Physics GetPhysics(){return Physics;}public override N FindComponent(Type t){if(t==typeof(SCR_AIVehicleUsageComponent))return Usage;return Rpl;}}')
$cs=$cs.Replace('public AICF_VehicleLease Lease;public bool Valid','public AICF_VehicleMovementState Movement=new AICF_VehicleMovementState();public AICF_VehicleMovementState GetMovementState(){return Movement;}public AICF_VehicleLease Lease;public bool Valid')
$fields=[regex]::Match($hint,'(?s)class AICF_UnstuckPathHint\s*\{(.*?)static const int MAXIMUM_LOCAL_POINTS').Groups[1].Value
$fields=(Translate $fields).Replace('public ref array<Vec> m_aPoints = {};','public List<Vec> m_aPoints = new List<Vec>();').Replace('float m_fOriginArc','double m_fOriginArc').Replace('public ref AICF_UnstuckMutationScope','public AICF_UnstuckMutationScope')
$current=(Translate (Body $hint 'IsCurrent')).Replace('array<Vec> repeated = {};','var repeated=new List<Vec>();').Replace('Read(m_Trip, m_Utility, group, vehicle, record, pilot, movement, reason)','Read(m_Trip, m_Utility, out group, out vehicle, out record, out pilot, out movement, out reason)')
$move=(Translate (Body $hint 'MoveCurrent')).Replace('array<AIWaypoint> queue = {};','var queue=new List<AIWaypoint>();')
$health=Translate (Body $hint 'HealthyActiveStationary')
$actual=@'
public class Physics:N {public Vec Velocity;public Vec GetVelocity(){return Velocity;}}
public enum EDamageState {UNDAMAGED,DAMAGED}public enum EAIActionState {RUNNING,FAILED}
public class SCR_AIVehicleUsageComponent:N {public EDamageState State;public EDamageState GetDamageState(){return State;}public static SCR_AIVehicleUsageComponent Cast(N n){return n as SCR_AIVehicleUsageComponent;}}
public class Zone:N {public double Health=1;public double GetHealthScaled(){return Health;}}
public class SCR_DamageManagerComponent:N {public Zone Zone=new Zone();public double Movement;public Zone GetDefaultHitZone(){return Zone;}public double GetMovementDamage(){return Movement;}public static SCR_DamageManagerComponent GetDamageManager(Vehicle v){return v.Damage;}}
public static class SCR_AIVehicleUsability {public static bool VehicleCanMove(Vehicle v){return v.CanMove;}public static bool VehicleIsOnFire(Vehicle v){return v.Fire;}}
public class AIWaypoint:IEntity {}
public class SCR_AIGroupUtilityComponent:N {public SCR_AIMoveActivity Current,Executed;public SCR_AIMoveActivity GetCurrentAction(){return Current;}public SCR_AIMoveActivity GetExecutedAction(){return Executed;}}
public class SCR_AIMoveActivity:N {public SCR_AIGroupUtilityComponent m_Utility;public AIWaypoint m_RelatedWaypoint;public bool Removed,Suspended;public EAIActionState State;public bool GetRemoveAction(){return Removed;}public bool GetActionIsSuspended(){return Suspended;}public EAIActionState GetActionState(){return State;}}
public class AICarMovementComponent:N {public AIAgent Agent;public Action OnPathRead;public List<Vec> Points=new List<Vec>();public AIAgent GetAIAgent(){return Agent;}public void GetCurrentPath(List<Vec> p){if(OnPathRead!=null)OnPathRead();p.AddRange(Points);}}
public class AIAgent:N {public IEntity Controlled;public AICarMovementComponent Movement;public bool Active=true,Counted=true;public int LOD;public IEntity GetControlledEntity(){return Controlled;}public AICarMovementComponent GetMovementComponent(){return Movement;}public bool IsAIActivated(){return Active;}public bool CountTowardsAIWorldLimit(){return Counted;}public int GetLOD(){return LOD;}}
public class SCR_AIGroupVehicle:N {}public class AIGroupMovementComponent:N {}
public class AICF_VehicleMovementState:N {public int Generation=1;public AIWaypoint Waypoint;public Vec Endpoint;public bool Bound=true;public int GetRouteGeneration(){return Generation;}public AIWaypoint GetRouteWaypoint(){return Waypoint;}public Vec GetRouteEndpoint(){return Endpoint;}public bool IsRouteWaypointBound(){return Bound;}}
public static class AICF_VehicleNativeSubgroup {public static HintEnvironment Env;public static bool Read(AICF_TransportTrip t,SCR_AIGroupUtilityComponent u,out SCR_AIGroup g,out Vehicle v,out SCR_AIGroupVehicle r,out AIAgent p,out AIGroupMovementComponent m,out string reason){g=Env.Owner.Trip.Assignment.Group;v=Env.Owner.Car;r=Env.Record;p=Env.Pilot;m=new AIGroupMovementComponent();reason="";return Env.NativeCurrent;}public static bool IsCurrentVehicleHandler(AICF_TransportTrip t,SCR_AIGroupUtilityComponent u,int h){return Env.NativeCurrent&&h==Env.Handler;}}
public static class AICF_VehicleNativeRouteProgress {public static bool SamePath(List<Vec>a,List<Vec>b){if(a.Count!=b.Count)return false;for(int i=0;i<a.Count;i++)if(a[i]!=b[i])return false;return true;}}
public class ActualHint:N {__FIELDS__ public const int MAXIMUM_AGE_MS=3000;public string Scope() __SCOPE_BODY__ public bool MoveCurrent() __MOVE__ public bool HealthyActiveStationary(Vehicle vehicle) __HEALTH__ public bool IsCurrent() __CURRENT__}
public class HintEnvironment {public Environment Owner;public ActualHint Hint;public SCR_AIGroupVehicle Record=new SCR_AIGroupVehicle();public AIAgent Pilot,CarAgent;public AICarMovementComponent CarMovement;public bool NativeCurrent=true;public int Handler=1;
 public static HintEnvironment Fresh(){var e=new HintEnvironment{Owner=Environment.Fresh()};var o=e.Owner;o.Trip.Preset=new N();o.Trip.PresetSlot=o.Slot;var group=o.Trip.Assignment.Group;var wp=new AIWaypoint{Id=11};group.Waypoint=wp;group.Queue.Add(wp);var u=new SCR_AIGroupUtilityComponent();group.Utility=u;var move=new SCR_AIMoveActivity{m_Utility=u,m_RelatedWaypoint=wp};u.Current=move;u.Executed=move;var points=new List<Vec>{new Vec(0,0,0),new Vec(0,0,10)};e.CarAgent=new AIAgent{Controlled=o.Car};e.CarMovement=new AICarMovementComponent{Agent=e.CarAgent,Points=points};e.Pilot=new AIAgent{Movement=e.CarMovement};o.Trip.Movement.Waypoint=wp;o.Trip.Movement.Endpoint=new Vec(0,0,20);
 e.Hint=new ActualHint{m_Trip=o.Trip,m_Controller=o.Controller,m_Assignment=o.Trip.Assignment,m_Lease=o.Trip.Lease,m_MutationScope=o.Scope,m_Group=group,m_Utility=u,m_Record=e.Record,m_Pilot=e.Pilot,m_Car=e.CarMovement,m_CarAgent=e.CarAgent,m_Move=move,m_Waypoint=wp,m_WaypointId=11,m_WaypointRpl=wp.Rpl,m_sWaypointRplId=wp.Rpl.Id().ToString(),m_vOrigin=o.Car.Origin,m_vEndpoint=o.Trip.Movement.Endpoint,m_vGoal=o.Trip.Assignment.Goal,m_iHandler=1,m_iRouteGeneration=1,m_iCapturedAtMs=1000,m_aPoints=new List<Vec>(points)};e.Hint.m_sScope=e.Hint.Scope();AICF_VehicleNativeSubgroup.Env=e;return e;}}
public static class HintExecute {public static int Run(){int n=0;Action<bool,string>check=(ok,label)=>{if(!ok)throw new Exception(label);n++;};var e=HintEnvironment.Fresh();check(e.Hint.IsCurrent(),"current actual hint positive");Action<Action<HintEnvironment>,string>negative=(change,label)=>{var x=HintEnvironment.Fresh();change(x);check(!x.Hint.IsCurrent(),label);};
 negative(x=>{x.Owner.Trip.Lease=null;x.Hint.m_Lease=null;x.Hint.m_MutationScope.m_Lease=null;},"weak captured lease cleared");negative(x=>{x.Owner.Trip.Assignment=null;x.Hint.m_Assignment=null;x.Hint.m_MutationScope.m_Assignment=null;},"weak captured assignment cleared");negative(x=>x.Handler=2,"native handler replaced");negative(x=>x.NativeCurrent=false,"native scope lost");negative(x=>x.Record=new SCR_AIGroupVehicle(),"native record replaced");negative(x=>x.Pilot=new AIAgent(),"pilot replaced");negative(x=>x.Owner.Slot.Generation++,"slot generation changed");negative(x=>x.Owner.Controller.m_bStopped=true,"controller stopped");negative(x=>AICF_MatchController.s_ActiveController=new AICF_MatchController(),"controller replaced");negative(x=>Clock.Now=4001,"real3s hint expired");negative(x=>Clock.Now=999,"clock regressed");
 negative(x=>x.CarMovement.Agent=new AIAgent(),"car brain replaced");negative(x=>x.Pilot.Movement=new AICarMovementComponent(),"pilot movement component replaced");negative(x=>x.CarAgent.Active=false,"inactive car");negative(x=>x.CarAgent.Counted=false,"uncounted car");negative(x=>x.CarAgent.LOD=1,"different car LOD");negative(x=>x.Pilot.Active=false,"inactive pilot");negative(x=>x.Hint.m_Pilot=null,"captured pilot gone");negative(x=>x.Hint.m_CarAgent=null,"captured car brain gone");negative(x=>x.Hint.m_Record=null,"captured record gone");
 negative(x=>x.Owner.Trip.Movement.Generation++,"route generation changed");negative(x=>x.Owner.Trip.Movement.Waypoint=new AIWaypoint(),"route waypoint replaced");negative(x=>x.Owner.Trip.Movement.Endpoint=new Vec(1,0,20),"global route endpoint changed");negative(x=>x.Owner.Trip.Assignment.Goal=new Vec(1,0,0),"global target changed");negative(x=>x.Owner.Trip.Movement.Bound=false,"route unbound");
 negative(x=>x.Hint.m_Utility.Current=new SCR_AIMoveActivity(),"selected native action changed");negative(x=>x.Hint.m_Utility.Executed=new SCR_AIMoveActivity(),"executed native action changed");negative(x=>x.Hint.m_Move.Removed=true,"move removed");negative(x=>x.Hint.m_Move.Suspended=true,"move suspended");negative(x=>x.Hint.m_Move.State=EAIActionState.FAILED,"move failed");negative(x=>x.Hint.m_Move.m_RelatedWaypoint=new AIWaypoint(),"move foreign waypoint");negative(x=>x.Owner.Trip.Assignment.Group.Waypoint=new AIWaypoint(),"current group waypoint foreign");negative(x=>x.Owner.Trip.Assignment.Group.Queue.Clear(),"route no longer queued");
 negative(x=>x.Hint.m_Waypoint.Id++,"waypoint entity id changed");negative(x=>x.Hint.m_Waypoint.Rpl.Proxy=true,"waypoint became proxy");negative(x=>x.Hint.m_Waypoint.Rpl.Value++,"waypoint rpl id changed");negative(x=>x.CarMovement.Points.Add(new Vec(0,0,12)),"path length changed");negative(x=>x.CarMovement.Points[1]=new Vec(1,0,10),"path point changed");
 negative(x=>x.Owner.Car.Usage.State=EDamageState.DAMAGED,"damaged usage");negative(x=>x.Owner.Car.Damage.Zone.Health=0.99,"health loss");negative(x=>x.Owner.Car.Damage.Movement=1,"movement damage");negative(x=>x.Owner.Car.Fire=true,"fire");negative(x=>x.Owner.Car.CanMove=false,"cannot move");negative(x=>x.Owner.Car.Physics.Velocity=new Vec(1.001,0,0),"moving too fast");
 negative(x=>x.CarMovement.OnPathRead=()=>x.Hint.m_Pilot=null,"native path getter clears pilot");negative(x=>x.CarMovement.OnPathRead=()=>x.Hint.m_Car=null,"native path getter clears car component");negative(x=>x.CarMovement.OnPathRead=()=>x.Hint.m_CarAgent=null,"native path getter clears car brain");negative(x=>x.CarMovement.OnPathRead=()=>x.Owner.Controller.m_bStopped=true,"native path getter callback stop");negative(x=>x.CarMovement.OnPathRead=()=>x.Handler=2,"native path getter callback handler swap");negative(x=>x.CarMovement.OnPathRead=()=>x.Owner.Trip.Lease=new AICF_VehicleLease(),"native path getter callback lease swap");negative(x=>x.CarMovement.OnPathRead=()=>x.CarMovement.Agent=new AIAgent(),"native path getter callback car brain swap");return n;}}
'@
$actual=$actual.Replace('__FIELDS__',$fields).Replace('__SCOPE_BODY__',(Translate (Body $hint 'Scope'))).Replace('__MOVE__',$move).Replace('__HEALTH__',$health).Replace('__CURRENT__',$current)
$close=$cs.LastIndexOf('}');$cs=$cs.Substring(0,$close)+$actual+"`n}"
Add-Type -TypeDefinition $cs
$count=[AICFHintIdentityActual.HintExecute]::Run()
$mutants=@(
 @('final handler callback', $cs.Replace('return AICF_VehicleNativeSubgroup.IsCurrentVehicleHandler(m_Trip, m_Utility, m_iHandler);','return true;')),
 @('full path equality', $cs.Replace('if (!AICF_VehicleNativeRouteProgress.SamePath(m_aPoints, repeated)) return false;',';')),
 @('post-path owner callback', $cs.Replace('if (!m_MutationScope.IsCurrent() || !MoveCurrent()) return false;',';'))
)
$i=0
foreach($mutant in $mutants){
 if($mutant[1]-eq$cs){throw "Hint mutation missing $($mutant[0])"}
 $name='AICFHintIdentityMutant'+$i;$types=Add-Type -TypeDefinition $mutant[1].Replace('AICFHintIdentityActual',$name) -PassThru
 $execute=$types|Where-Object{$_.FullName-eq($name+'.HintExecute')};$rejected=$false
 try{$null=$execute.GetMethod('Run').Invoke($null,@())}catch{$rejected=$true}
 if(!$rejected){throw "Executable hint mutant escaped $($mutant[0])"};$i++
}
"PASS Unstuck hint identity: actual_current_handler_owner_car_path_controls=$count executable_unsafe_mutants=$i native=NOT_RUN"
